// Tunables.
const MAX_FLUSHES = 4;
const BATCH_SIZE = 30;
const MAX_ENTRIES = 300;
const MAX_ERRORS = 20;
const CLOCK = Date.UTC(2026, 10, 2, 7, 15, 0);
const OBSERVED_TYPES = ["longtask", "event", "largest-contentful-paint", "layout-shift", "resource", "paint", "navigation", "first-input"];

const work = window.__benchmarkWork;
const state = { buffer: [], flushes: 0, bytes: 0, total: 0, vitals: { lcp: 0, cls: 0, inp: 0, fcp: 0, longTasks: 0 }, errors: 0, requests: 0 };

function now() {
    return CLOCK + Math.round(performance.now());
}

function sink(payload) {
    state.bytes += payload.length;
}

function flush(reason) {
    if (!state.buffer.length || state.flushes >= MAX_FLUSHES)
        return;
    state.flushes++;
    const batch = state.buffer.splice(0, state.buffer.length);
    sink(JSON.stringify({ t: now(), reason, url: location.href, vitals: state.vitals, entries: batch }));
}

function record(kind, data) {
    if (state.total >= MAX_ENTRIES)
        return;
    state.total++;
    state.buffer.push({ kind, ts: Math.round(performance.now()), ...data });
    if (state.buffer.length >= BATCH_SIZE)
        flush("batch");
}

function handleEntry(entry) {
    switch (entry.entryType) {
    case "longtask":
        state.vitals.longTasks++;
        record("longtask", { start: Math.round(entry.startTime), duration: Math.round(entry.duration), attribution: entry.attribution ? entry.attribution.length : 0 });
        break;
    case "event":
        if (entry.interactionId)
            state.vitals.inp = Math.max(state.vitals.inp, entry.duration);
        if (entry.duration >= 16)
            record("event", { name: entry.name, duration: entry.duration, delay: Math.round(entry.processingStart - entry.startTime), target: entry.target ? entry.target.nodeName : "" });
        break;
    case "first-input":
        record("fid", { name: entry.name, delay: Math.round(entry.processingStart - entry.startTime) });
        break;
    case "largest-contentful-paint":
        state.vitals.lcp = Math.round(entry.startTime);
        record("lcp", { time: Math.round(entry.startTime), size: entry.size, element: entry.element ? entry.element.nodeName : "", url: entry.url });
        break;
    case "layout-shift":
        if (!entry.hadRecentInput)
            state.vitals.cls += entry.value;
        record("shift", { value: entry.value, sources: entry.sources ? entry.sources.length : 0 });
        break;
    case "resource":
        record("resource", { name: entry.name, type: entry.initiatorType, duration: Math.round(entry.duration), size: entry.transferSize });
        break;
    case "paint":
        if (entry.name === "first-contentful-paint")
            state.vitals.fcp = Math.round(entry.startTime);
        record("paint", { name: entry.name, time: Math.round(entry.startTime) });
        break;
    case "navigation":
        record("navigation", { type: entry.type, dcl: Math.round(entry.domContentLoadedEventEnd), load: Math.round(entry.loadEventEnd) });
        break;
    }
}

function observe() {
    const supported = (window.PerformanceObserver && PerformanceObserver.supportedEntryTypes) || [];
    for (const type of OBSERVED_TYPES) {
        if (!supported.includes(type))
            continue;
        try {
            const observer = new PerformanceObserver((list) => {
                for (const entry of list.getEntries())
                    handleEntry(entry);
            });
            const options = { type, buffered: true };
            if (type === "event")
                options.durationThreshold = 16;
            observer.observe(options);
        } catch (e) {}
    }
}

function wrapFetch() {
    const original = window.fetch;
    if (typeof original !== "function")
        return;
    window.fetch = function (input, init) {
        const start = performance.now();
        const method = (init && init.method) || (input && input.method) || "GET";
        const url = typeof input === "string" ? input : (input && input.url) || String(input);
        const result = original.apply(this, arguments);
        const done = (response) => {
            state.requests++;
            record("fetch", { method, url, status: response && response.status, duration: Math.round(performance.now() - start) });
        };
        result.then(done, () => done(null));
        return result;
    };
}

function wrapXhr() {
    const proto = window.XMLHttpRequest && XMLHttpRequest.prototype;
    if (!proto)
        return;
    const open = proto.open;
    const send = proto.send;
    proto.open = function (method, url) {
        this.__rum = { method, url: String(url), start: 0 };
        return open.apply(this, arguments);
    };
    proto.send = function () {
        const info = this.__rum;
        if (info) {
            info.start = performance.now();
            this.addEventListener("loadend", () => {
                state.requests++;
                record("xhr", { method: info.method, url: info.url, status: this.status, duration: Math.round(performance.now() - info.start) });
            });
        }
        return send.apply(this, arguments);
    };
}

function listenForErrors() {
    window.addEventListener("error", (event) => {
        if (state.errors++ >= MAX_ERRORS)
            return;
        record("error", { message: String(event.message), source: event.filename, line: event.lineno, column: event.colno, resource: event.target && event.target.nodeName !== undefined && event.target !== window ? event.target.nodeName : "" });
    }, true);
    window.addEventListener("unhandledrejection", (event) => {
        if (state.errors++ >= MAX_ERRORS)
            return;
        record("rejection", { reason: String(event.reason && event.reason.message ? event.reason.message : event.reason) });
    });
}

function start() {
    performance.mark("rum-start");
    observe();
    wrapFetch();
    wrapXhr();
    listenForErrors();
    document.addEventListener("visibilitychange", () => {
        if (document.visibilityState === "hidden")
            flush("hidden");
    });
    window.addEventListener("pagehide", () => flush("pagehide"));
    window.addEventListener("load", () => {
        work?.track(new Promise((resolve) => {
            setTimeout(() => {
                flush("load");
                resolve();
            }, 0);
        }));
    }, { once: true });
    const mon = window.perfmon;
    if (mon && mon.ac) {
        for (const command of mon.ac.splice(0))
            record("command", { name: command[0] });
        mon.send = () => flush("manual");
    }
    window.__rum = { state };
    work?.settled("rum");
}

start();
